import {ROADS} from './road-layout.js?v=detail18';
// Route on road centrelines, avoiding a whole-world grid search for background traffic.
export function roadRoute(start,end){const lists=ROADS.map(r=>{const h=r.w>r.d;return {h,fixed:h?r.z:r.x,min:(h?r.x-r.w/2:r.z-r.d/2),max:(h?r.x+r.w/2:r.z+r.d/2),points:[]};});const key=p=>p.x.toFixed(3)+','+p.z.toFixed(3),nodes=new Map(),add=(l,p)=>{l.points.push(p);const k=key(p);if(!nodes.has(k))nodes.set(k,{p,edges:new Map()});};for(const l of lists){for(const v of [l.min,l.max])add(l,l.h?{x:v,z:l.fixed}:{x:l.fixed,z:v});for(const p of [start,end])if(Math.abs((l.h?p.z:p.x)-l.fixed)<.01&&(l.h?p.x:p.z)>=l.min-.01&&(l.h?p.x:p.z)<=l.max+.01)add(l,p);}
 for(let i=0;i<lists.length;i++)for(let j=i+1;j<lists.length;j++){const a=lists[i],b=lists[j];if(a.h!==b.h){const h=a.h?a:b,v=a.h?b:a;if(v.fixed>=h.min&&v.fixed<=h.max&&h.fixed>=v.min&&h.fixed<=v.max){const p={x:v.fixed,z:h.fixed};add(a,p);add(b,p);}}else if(a.fixed===b.fixed){const lo=Math.max(a.min,b.min),hi=Math.min(a.max,b.max);if(lo<=hi)for(const t of [lo,hi]){const p=a.h?{x:t,z:a.fixed}:{x:a.fixed,z:t};add(a,p);add(b,p);}}}
 for(const l of lists){l.points.sort((a,b)=>l.h?a.x-b.x:a.z-b.z);for(let i=1;i<l.points.length;i++){const a=l.points[i-1],b=l.points[i],ka=key(a),kb=key(b),d=Math.hypot(a.x-b.x,a.z-b.z);if(d){nodes.get(ka).edges.set(kb,d);nodes.get(kb).edges.set(ka,d);}}}
 const a=key(start),b=key(end);if(!nodes.has(a)||!nodes.has(b))return [];const dist=new Map([[a,0]]),parent=new Map(),open=new Set([a]);while(open.size){let k;for(const candidate of open)if(k===undefined||dist.get(candidate)<dist.get(k))k=candidate;open.delete(k);if(k===b){const path=[];while(k!==a){path.push(nodes.get(k).p);k=parent.get(k);}return path.reverse();}for(const [next,weight]of nodes.get(k).edges){const d=dist.get(k)+weight;if(d<(dist.get(next)??Infinity)){dist.set(next,d);parent.set(next,k);open.add(next);}}}return [];}
